@lru_cache(maxsize=None)
def _array(name):
    """Decode a native array once, then keep the read-only reference cached."""
    shape, dtype = _SHAPES[name]
    raw = zlib.decompress(base64.b85decode(_BLOBS[name]))
    result = np.frombuffer(raw, dtype=np.dtype(dtype)).reshape(shape)
    result.flags.writeable = False
    return result

