def collision_map(race):
    """Preclassified terrain packed for the arcade's hidden playfield columns."""
    return _array(f'collision_pf{race}'), _array(f'collision_mo{race}')

def row_bases(race):
    """Absolute reference heights by terrain lattice row."""
    return _array(f'rowbases{race}')
